L21_1.m_Pos = "R"
L21_1.m_Talk_KOREA = "그러는 너는 이런 시기에 꽤 한가해 보이는군."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "そういう君はこんな時期なのに随分と暇そうだな。"
L21_1.m_Talk_ENG = "Well, it seems you're quite free in these busy times."
