L22_1.m_CharStrID = "CHARADE_ADMIN_NULL_NULL"
L22_1.m_Pos = "R"
L22_1.m_Talk_KOREA = "지난 회의에서도 그라운드 원은 조용할 날이 없다고 불평하지 않았나?"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "前回の会議でもグラウンド・ワンは毎日事件だらけだと文句を言っていなかったか？"
L22_1.m_Talk_ENG = "Didn't you complain last time during the meeting about how not a day goes by without trouble at Ground One?"
L22_1.m_Talk_TWN = "我記得在上次會議中你不是還抱怨，說什麼G1沒一天是安寧的。"
L22_1.m_Talk_SCN = "我记得上次的会议你也在抱怨，G1就没有一天安宁的日子。"
