L23_1.m_CharStrID = "CHARADE_ADMIN_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Talk_KOREA = "네가 소임을 다하지 않으면 다른 직원들 기강도 해이해질 수밖에 없다."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "君がしっかりしなければ、他の社員も気が緩むものだ。"
L23_1.m_Talk_ENG = "Just know that your employees will slack off if you do not do your duties."
L23_1.m_Talk_TWN = "你這樣不善盡職責的話，也不能怪底下的人紀律渙散吧。"
L23_1.m_Talk_SCN = "不尽职尽责一点的话，其他职员的纪律就更别说了。"
L23_1.m_Talk_DEU = "Just know that your employees will slack off if you do not do your duties."
L23_1.m_Talk_FRA = "Just know that your employees will slack off if you do not do your duties."
