L25_1.m_CharStrID = "GROUND_ADMIN_NULL_NULL"
L25_1.m_Pos = "L"
L25_1.m_Talk_KOREA = "보고서 봤어. 이번에 그 미친 테러리스트의 신병을 확보했다면서?"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "報告書は読んだ。あのイカれたテロリストの身柄を確保したそうじゃないか。"
