L32_1 = {}
L32_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE6@32#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 6800310
L32_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE6"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_FilterType = "NCFT_NORMAL"
L32_1.m_BGFileName = "PROLOGUE_02"
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_fFlashBangTime = 0.5
L32_1.m_StartFXSoundName = "FX_COMBAT_ALL_MAGIC_SPELL_LIGHT_02"
L32_1.m_CharStrID = "GROUND_ADMIN_NULL_NULL"
L32_1.m_Pos = "C"
L32_1.m_bCharHologramEffect = true
L32_1.m_Talk_KOREA = "보고서에는 퍼스트윙이 체포된 계기가 육익 내부에서 일어난 내분 때문이라고 적어 뒀지."
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "報告書にはファーストウイングが逮捕されたきっかけが六翼の内部の抗争にあると書かれていた。"
L32_1.m_Talk_ENG = "The report said that Firstwing was arrested due to the internal conflict caused within Six Wings."
L32_1.m_Talk_TWN = "報告上說，是因為六翼發生內鬨，你們才得以抓到弗斯特薇。"
L32_1.m_Talk_SCN = "报告上写的抓获弗特薇的契机，是因为六翼内部发生的内斗。"
L32_1.m_Talk_DEU = "The report said that Firstwing was arrested due to the internal conflict caused within Six Wings."
L32_1.m_Talk_FRA = "The report said that Firstwing was arrested due to the internal conflict caused within Six Wings."
L33_1 = {}
L33_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE6@33#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 6800310
L33_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE6"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SERIOUS"
L33_1.m_CharStrID = "GROUND_ADMIN_NULL_NULL"
L33_1.m_Pos = "C"
L33_1.m_Talk_KOREA = "하지만 우리는 내분의 원인이나, 퍼스트윙을 제압한 인물에 대해서는 전달받지 못했어."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "でも私たちは抗争の原因も、ファーストウイングを制圧した人物についても知らされていない。"
L33_1.m_Talk_ENG = "But we never received any information regarding the cause of the conflict or who was responsible for arresting Firstwing."
L33_1.m_Talk_TWN = "但內鬨的原因，或是是誰制服弗斯特薇？這些資訊卻一無所知。"
L33_1.m_Talk_SCN = "但我们没有收到内斗的原因，或者关于制服了弗特薇的人物的信息。"
L33_1.m_Talk_DEU = "But we never received any information regarding the cause of the conflict or who was responsible for arresting Firstwing."
L33_1.m_Talk_FRA = "But we never received any information regarding the cause of the conflict or who was responsible for arresting Firstwing."
L34_1 = {}
L34_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE6@34#Talk"
L34_1.m_CutScenProcessKey = 34
L34_1.m_CutScenID = 6800310
