L34_1.m_CharStrID = "GROUND_ADMIN_NULL_NULL"
L34_1.m_Pos = "C"
L34_1.m_Talk_KOREA = "수장도, 그 호위도 클리포트 게임 당시에 출몰했을 텐데."
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "組織のトップも、護衛も、クリフォトゲームのときに出没していたはずなのに。"
L34_1.m_Talk_ENG = "Their leader and his bodyguard both appeared during the Qliphoth Game."
L34_1.m_Talk_TWN = "不管是帶頭的或是保鑣，應該都曾經出現在逆卡巴拉遊戲中。"
L34_1.m_Talk_SCN = "无论是领袖还是他的护卫，在神圣战役时都应该出现过。"
L34_1.m_Talk_DEU = "Their leader and his bodyguard both appeared during the Qliphoth Game."
L34_1.m_Talk_FRA = "Their leader and his bodyguard both appeared during the Qliphoth Game."
