L26_1.m_fTitleTalkTime = 0
L27_1 = "<color=#ffd34c>■■■</color> ??????????????????????\n<color=#ffd34c>■ ■</color> 아무리 카운터라고 해도 저런 거에 맞으면 죽지 않을까?\n<color=#ffd34c>■ ■</color> 아니 그냥 흔적도 안 남겠는데?\n<color=#ffd34c>■■■</color> 그럼 경기는 어떻게 되는 거임????????\n<color=#ffd34c>■■</color> 야, 뭔가 발견함! 다들 리플레이 다시 돌려서 봐봐!\n<color=#ffd34c>■■</color> 번개가 떨어지기 직전에 펠리세트가 들고 있는 방패가 변형됨.\n<color=#ffd34c>■■■</color> 진짜네??? 저게 펠리세트가 한 거라고?\n<color=#ffd34c>■■■</color> 펠리세트 사실 카운터라는 설 진짜 아님???\n<color=#ffd34c>■ ■</color> 잠깐, 저게 정말로 의도된 공격이었다면, 어떻게 되는 거야?\n<color=#ffd34c>■ ■</color> 카나리아 스쿼드가 설마 챔피언을 죽이려고 했던 거야?"
L26_1.m_SubTitle_KOREA = L27_1
L26_1.m_fSubTitleTalkTime = 0
L27_1 = "<color=#ffd34c>■■■</color> ？？？？？？？\n<color=#ffd34c>■ ■</color> さすがのカウンターでもあれを食らったら死ぬんじゃない？\n<color=#ffd34c>■ ■</color> 跡形もなく消えるでしょうね。\n<color=#ffd34c>■■■</color> じゃあ試合はどうなるんだ？？？？\n<color=#ffd34c>■■</color> おい、何か見つけたぞ！　みんなリプレイで見てみろ！\n<color=#ffd34c>■■</color> 雷が落ちる前、フェリセットが持っていた盾が変形した。\n<color=#ffd34c>■■■</color> 本当だ。あれはフェリセットがやったのか？\n<color=#ffd34c>■■■</color> フェリセット実はカウンター説ってまじだったのか？？\n<color=#ffd34c>■ ■</color> 待って、あれを意図的にやったんだとしたら、どうなるんだ？\n<color=#ffd34c>■ ■</color> カナリア・スクワッドはまさかチャンピオンを殺そうとしていたのか？"
L26_1.m_SubTitle_JPN = L27_1
L27_1 = "<color=#ffd34c>■■■</color> ??????????????????????\n<color=#ffd34c>■ ■</color> Wouldn't that lightning bolt instantly kill anyone even if they were Counters?\n<color=#ffd34c>■ ■</color> It looked like it wouldn't even leave a trace.\n<color=#ffd34c>■■■</color> What's gonna happen to the match now????????\n<color=#ffd34c>■■</color> Hey, I found something! Guys, go check out the replay!\n<color=#ffd34c>■■</color> Right before the lightning bolt hit, Félicette's shield changed shape.\n<color=#ffd34c>■■■</color> You're right!! You mean that Félicette did that?\n<color=#ffd34c>■■■</color> Maybe people were right about Félicette being a Counter???\n<color=#ffd34c>■ ■</color> Wait, but if that's considered an intentional attack, what happens next?\n<color=#ffd34c>■ ■</color> Whoa, did Canary Squad just try to assassinate the champion?"
L26_1.m_SubTitle_ENG = L27_1
L27_1 = "<color=#ffd34c>■■■</color> ？？？？？？？？？？？？？？？\n<color=#ffd34c>■ ■</color> 被那道雷劈到就算是制裁者也會沒命吧？\n<color=#ffd34c>■ ■</color> 哇，毫髮無傷欸？\n<color=#ffd34c>■■■</color> 比賽會如何進行下去？？？？\n<color=#ffd34c>■■</color> 欸，好像有什麼東西！你們再看一下重播！\n<color=#ffd34c>■■</color> 雷劈下來前費莉塞特的盾牌變形咧？\n<color=#ffd34c>■■■</color> 真的欸？？？是費莉塞特弄的嗎？\n<color=#ffd34c>■■■</color> 難道說費莉塞特是制裁者的傳言是真的？？？\n<color=#ffd34c>■ ■</color> 等等，如果這是在計畫內的攻擊，那現在會怎麼樣？\n<color=#ffd34c>■ ■</color> 金絲雀小隊是真的想要冠軍的命嗎？"
L26_1.m_SubTitle_TWN = L27_1
L27_1 = "<color=#ffd34c>■■■</color>？？？？？？？？？？？\n<color=#ffd34c>■ ■</color>就算是制裁者，如果被那个击中，应该必死无疑吧？\n<color=#ffd34c>■ ■</color>连个痕迹都不会留下吧？\n<color=#ffd34c>■■■</color>那比赛怎么办？？？？？？？\n<color=#ffd34c>■■</color>喂，我发现了一个东西！大家快退回去看看！\n<color=#ffd34c>■■</color>闪电掉下来之前，菲利塞特举着的盾牌变形了。\n<color=#ffd34c>■■■</color>是真的诶？？？那么那个霹雳是菲利塞特弄出来的？\n<color=#ffd34c>■■■</color>其实菲利塞特是制裁者的那个传闻是真的吧？\n<color=#ffd34c>■ ■</color>等等，如果那个攻击真的是预谋好的，那接下来会怎么样？\n<color=#ffd34c>■ ■</color>金丝雀小队难道是想杀了冠军？"
L26_1.m_SubTitle_SCN = L27_1
L27_1 = "<color=#ffd34c>■■■</color> ??????????????????????\n<color=#ffd34c>■ ■</color> Wouldn't that lightning bolt instantly kill anyone even if they were Counters?\n<color=#ffd34c>■ ■</color> It looked like it wouldn't even leave a trace.\n<color=#ffd34c>■■■</color> What's gonna happen to the match now????????\n<color=#ffd34c>■■</color> Hey, I found something! Guys, go check out the replay!\n<color=#ffd34c>■■</color> Right before the lightning bolt hit, Félicette's shield changed shape.\n<color=#ffd34c>■■■</color> You're right!! You mean that Félicette did that?\n<color=#ffd34c>■■■</color> Maybe people were right about Félicette being a Counter???\n<color=#ffd34c>■ ■</color> Wait, but if that's considered an intentional attack, what happens next?\n<color=#ffd34c>■ ■</color> Whoa, did Canary Squad just try to assassinate the champion?"
L26_1.m_SubTitle_DEU = L27_1
L27_1 = "<color=#ffd34c>■■■</color> ??????????????????????\n<color=#ffd34c>■ ■</color> Wouldn't that lightning bolt instantly kill anyone even if they were Counters?\n<color=#ffd34c>■ ■</color> It looked like it wouldn't even leave a trace.\n<color=#ffd34c>■■■</color> What's gonna happen to the match now????????\n<color=#ffd34c>■■</color> Hey, I found something! Guys, go check out the replay!\n<color=#ffd34c>■■</color> Right before the lightning bolt hit, Félicette's shield changed shape.\n<color=#ffd34c>■■■</color> You're right!! You mean that Félicette did that?\n<color=#ffd34c>■■■</color> Maybe people were right about Félicette being a Counter???\n<color=#ffd34c>■ ■</color> Wait, but if that's considered an intentional attack, what happens next?\n<color=#ffd34c>■ ■</color> Whoa, did Canary Squad just try to assassinate the champion?"
