L29_1.m_CharStrID = L30_1
L30_1 = "이, 이럴 수가!! 위기의 순간에서 기적 같이 부활한 노엘 선수!!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "な、なんと！！　ピンチの瞬間に奇跡のごとく復活したノエル選手！！"
