L30_1 = "N-no way!! In a moment of crisis, Noelle is miraculously back in action!!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "這、這怎麼可能！！在危急時刻奇跡般復活的洛艾兒選手！！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "这、这怎么可能！！在危急时刻奇迹般复活的诺艾尔选手！！"
