L34_1[L35_1] = true
L35_1 = "사슬검에 의한 전방위 방어. 발톱처럼 서서히 옭아매다가, 단숨에 끌어당기는 것이 그녀의 스타일이죠."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "蛇腹剣による全方位の防御。爪のように徐々に縛り、一気に引き寄せるのが彼女のやり方です。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Her style is an all-round defense with her whip sword, slowly trapping her opponent as if sinking in her claw, then pulling her target in before being able to react."
L34_1.m_Talk_ENG = L35_1
L35_1 = "使用鏈劍進行全方位的防禦。像爪子一樣慢慢纏繞收緊，然後一瞬間把目標拉扯過來，這是她的風格。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "使用链剑进行全方位的防御。像爪子一样慢慢缠绕收紧，然后一瞬间把目标拉扯过来，这是她的风格。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Her style is an all-round defense with her whip sword, slowly trapping her opponent as if sinking in her claw, then pulling her target in before being able to react."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Her style is an all-round defense with her whip sword, slowly trapping her opponent as if sinking in her claw, then pulling her target in before being able to react."
